import audio_logic
from audio_logic import NoteEngine


def _make_engine():
    """Build a NoteEngine without knowing its exact constructor signature."""
    try:
        return NoteEngine()
    except TypeError:
        return NoteEngine(4)


def _recording_engine():
    engine = _make_engine()
    emitted = []
    engine._emit = lambda key, active: emitted.append((key, active))
    return engine, emitted


def _voice(key):
    return audio_logic._Voice(key, audio_logic.frequency_for_key(key))


def test_key_up_stops_a_sounding_note_and_returns_none():
    # meridian: unit_id=ebf2a81ddbb1 requirement=1-2
    engine, emitted = _recording_engine()
    engine._active.clear()
    engine._pending.clear()
    engine._releasing.clear()
    voice = _voice("a")
    engine._active["a"] = voice

    result = engine.key_up("a")

    assert result is None
    assert "a" not in engine._active
    assert voice in engine._releasing
